1. What is the output of the following code?
class A {
    public void show() { System.out.println("A"); }
}
class B extends A {
    @Override
    public void show() { System.out.println("B"); }
}
class C extends B {
    @Override
    public void show() { System.out.println("C"); }
}
A obj = new C();
obj.show();

2. Will this code compile? What is the output?
class Parent {
    int x = 100;
    public int getValue() { return x; }
}
class Child extends Parent {
    int x = 200;
    @Override
    public int getValue() { return x; }
}
Parent p = new Child();
System.out.println(p.x);         // Line A
System.out.println(p.getValue()); // Line B

3. How many overloaded methods does this class have? Will it compile?
class Calculator {
    public int add(int a, int b) { return a + b; }
    public double add(int a, int b) { return a + b; }  // Line X
    public int add(double a, double b) { return (int)(a + b); }
    public int add(int a, int b, int c) { return a + b + c; }
}

